package net.civeira.phylax.feature.access.dcrinitialaccesstoken.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.dcrinitialaccesstoken.domain.DcrInitialAccessToken;
import net.civeira.phylax.feature.access.dcrinitialaccesstoken.domain.valueobject.UsesVO;

class UsesValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of uses of dcr initial access token")
  void test_uses_value_holder_assign_plain_value() {
    Object holder = new Object();
    UsesValueHolder<Object> value = new UsesValueHolder<>(holder);
    Assertions.assertSame(holder, value.uses(1), "Setters must return the holder");
    Assertions.assertTrue(value.getUsesValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getUses().orElse(null), "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of uses of dcr initial access token")
  void test_uses_value_holder_assign_value_object() {
    Object holder = new Object();
    UsesValueHolder<Object> value = new UsesValueHolder<>(holder);
    UsesVO vo = UsesVO.from(1);
    Assertions.assertFalse(value.getUsesValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.uses(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getUsesValue().orElseThrow());
    Assertions.assertSame(holder, value.uses(Optional.empty()));
    Assertions.assertFalse(value.getUsesValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.uses(Optional.of(vo)));
    Assertions.assertSame(vo, value.getUsesValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of uses of dcr initial access token against the original")
  void test_uses_value_holder_read() {
    Object holder = new Object();
    UsesValueHolder<Object> value = new UsesValueHolder<>(holder);
    UsesVO vo = UsesVO.from(1);
    UsesVO other = UsesVO.from(1);
    DcrInitialAccessToken original = Mockito.mock(DcrInitialAccessToken.class);
    Mockito.when(original.getUsesValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readUses(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readUses(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.uses(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readUses(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readUses(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of uses of dcr initial access token")
  void test_uses_value_holder_unset() {
    Object holder = new Object();
    UsesValueHolder<Object> value = new UsesValueHolder<>(holder);
    UsesVO vo = UsesVO.from(1);
    value.uses(vo);
    Assertions.assertSame(holder, value.unsetUsesIfMatches("uses_other"));
    Assertions.assertTrue(value.getUsesValue().isPresent(), "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetUsesIfMatches("uses"));
    Assertions.assertFalse(value.getUsesValue().isPresent(), "The field name must clear the value");
    value.uses(vo);
    Assertions.assertSame(holder, value.unsetUses());
    Assertions.assertFalse(value.getUsesValue().isPresent(), "Unset must clear the value");
  }
}
